from h import *
R(9590770,"شوكولاتة ساخنة قليلة السعرات [80 سعرة حرارية فقط]",
"خيار صحي للشوكولاتة الساخنة، قليل السعرات الحرارية ولذيذ!",
"حصة واحدة","حصة واحدة",
["1.5 كوب حليب لوز غير محلّى أو أي حليب نباتي من اختيارك","1 ملعقة كبيرة كاكاو نيء غير محلّى","1-2 ملعقة صغيرة شراب القيقب","¼ ملعقة صغيرة خلاصة فانيليا طبيعية اختياري","رشة ملح البحر اختياري"],
["اخفق جميع المكونات في قدر صغير وسخّنها على حرارة متوسطة إلى عالية حتى تصل إلى درجة الحرارة المطلوبة.","تمتّع بها فورًا."],
["المعلومات الغذائية تعكس ملعقة صغيرة واحدة من شراب القيقب. للحصول على وصفة بدون سكر، تجاهل شراب القيقب. للحصول على وصفة خالية من المكسرات، استخدم حليب الصويا أو حليب الشوفان بدلًا من اللوز. لكن التزم بالأنواع غير المحلاة لتجنب السكر المضاف. للحصول على نسخة أغنى (وليست قليلة السعرات بالطبع) استخدم حليب جوز الهند المعلب. حضّرها كشوكولاتة ساخنة بالنعناع بإضافة ⅛ ملعقة صغيرة من خلاصة النعناع."])
R(9591321,"سلطة الشمندر والبطاطا الحلوة",
"سلطة الشمندر والبطاطا الحلوة طبق نابض بالحياة ومغذٍّ يجمع بين الحلاوة الترابية للشمندر المشوي والغنى الكريمي للبطاطا الحلوة.",
"6 حصص","حصة واحدة",
["3 أكواب شمندر مقطع مكعبات حوالي 1 رطل (مقطع إلى مكعبات بسمك نصف بوصة)","3 أكواب بطاطا حلوة مقطعة مكعبات حوالي 1 رطل (مقطعة إلى مكعبات بسمك نصف بوصة)","½ كوب أرز بسمتي مغسول","1 كوب مرق خضار","6 أكواب سبانخ صغيرة (بيبي) حوالي عبوة 5 أونصات","1.5 كوب فاصوليا كانليني بيضاء حوالي علبة 15 أونصة، مصفاة + مغسولة","½ كوب نصفا حبات بيكان","¼ كوب توت بري مجفف أو رمان","¼ كوب طحينة","3 ملاعق كبيرة خل التفاح","2 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق الزنجبيل","ملح + فلفل حسب الرغبة"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (218° مئوية) بوضع التحميص بالهواء الساخن (الحمل الحراري) وبطّن صينية خبز بورق الزبدة.","رتّب مكعبات الشمندر والبطاطا الحلوة المقشرة في طبقة واحدة على الصينية ورشّ عليها الملح والفلفل الأسود بسخاء. حمّصها لمدة 20-25 دقيقة أو حتى تصبح الحواف ذهبية اللون وتلين المكعبات عند غرزها بالشوكة.","في هذه الأثناء، ضع الأرز ومرق الخضار في قدر صغير واتركهما حتى يغليا. ثم خفّف الحرارة واتركه على نار هادئة حتى ينضج ويتشرب معظم السائل. قلّبه بالشوكة وضعه جانبًا ليبرد قليلًا.","ضع جميع مكونات تتبيلة السلطة في وعاء صغير واخفقها حتى تمتزج. ضعها جانبًا.","عندما تصبح الخضار المحمصة والأرز جاهزين، ضعهما مع جميع مكونات السلطة المتبقية في وعاء خلط. ثم اسكب تتبيلة السلطة واخلط جيدًا حتى تتغلف المكونات بالتساوي. تذوّق الملح والفلفل وعدّلهما إذا لزم الأمر."],
["قطّع مكعبات الشمندر والبطاطا الحلوة بأكبر قدر ممكن من التجانس ليتم النضج بالتساوي.","لتوفير وقت التحضير، يمكنك استخدام بطاطا حلوة وشمندر مقطعين مسبقًا إلى مكعبات.","إذا لم يكن لديك فرن بالهواء الساخن (حمل حراري)، فحمّص الخضار لفترة أطول قليلًا، حتى تلين عند غرزها بالشوكة وتصبح الحواف ذهبية اللون.","احتفظ بالمتبقي في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام."],
{"For the Dressing":"للتتبيلة"})
R(9592646,"قرع السباغيتي في القلاية الهوائية",
"قرع سباغيتي مثالي في القلاية الهوائية في كل مرة! سهل ويحتاج إلى مكونات قليلة فقط، وجاهز في 25 دقيقة أو أقل.",
"حصتان","حصة واحدة",
["2 رطل قرع سباغيتي (حبة صغيرة واحدة، لكن زنها للحصول على أدق النتائج)","2 ملعقة صغيرة زيت الأفوكادو أو ما تختاره، *يُحذف للحصول على وصفة بدون زيت، انظر الملاحظات","½ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود اختياري","¼ ملعقة صغيرة مسحوق الثوم اختياري","¼ ملعقة صغيرة بابريكا مدخنة اختياري","جبن بارميزان نباتي","بقدونس طازج"],
["اقطع شريحة رفيعة من طرفي القرع ثم اقطعه إلى نصفين طوليًا بأكبر قدر ممكن من التساوي. ضع النصفين في سلة القلاية الهوائية وجانب القطع لأعلى. ثم رشّ عليهما الزيت (إن استخدمته) ووزّع التوابل بالتساوي.","اطهُه على 360 درجة فهرنهايت (180° مئوية) لمدة 20 دقيقة، أو حتى تخترق الشوكة اللب بسهولة. (قد يختلف ذلك بحسب حجم القرع.)","بعد النضج، انقله إلى طبق وفكّك الداخل بالشوكة. ثم أضف جبن البارميزان والبقدونس الطازج، إن استخدمتهما، وبالهناء والشفاء."],
["اقطع القرع إلى نصفين متساويين قدر الإمكان ليتم النضج بالتساوي. قد تطهو القلايات الهوائية المختلفة بسرعات مختلفة. أنا أستخدم نينجا فودي (Ninja Foodi)، لكن إن كان لديك طراز مختلف، فابدأ بتفقد القرع عند مرور 15 دقيقة تقريبًا واطهُه حتى يلين بالشوكة. حجم قرع السباغيتي سيحدد وقت الطهي. طهوت قرعة وزنها 2 رطل في نينجا فودي لمدة 20 دقيقة بنتائج مثالية. إذا كانت القرعة أصغر أو أكبر، فعدّل وقت الطهي. *للحصول على وصفة بدون زيت، احذف الزيت ورشّ أو اسكب قليلًا من مرق الخضار على الوجه للترطيب قبل الطهي. أستخدم نينجا فودي سعة 8 كوارت لكن أي طراز يتسع للقرع من الداخل سيعمل جيدًا. وإذا لم يكن لديك قلاية هوائية، فلا يزال بإمكانك تحضيرها في الفرن. سخّنه مسبقًا على 400 درجة فهرنهايت (200° مئوية)، وقطّع القرع إلى نصفين وتبّله كما هو موضح. ثم اخبزه على صينية مبطنة بورق الزبدة لمدة 35-45 دقيقة، حتى يلين بالشوكة. يُحفظ المتبقي في الثلاجة في وعاء محكم الإغلاق لمدة 3 أيام أو يُجمّد لمدة تصل إلى 3 أشهر."],
{"Optional Garnishes":"مزيّنات اختيارية"})
R(9596194,"خبز التفاح النباتي [بدون زيت]",
"خبز التفاح النباتي هذا شديد الرطوبة وسهل التحضير في وعاء واحد فقط. حلو بشكل لذيذ مع دوامة قرفة جميلة.",
"12 شريحة (رغيف واحد مقاس 5\"×9\")","حصة واحدة",
["270 غرامًا دقيق القمح الكامل حوالي 2¼ كوب (استخدم الوزن للحصول على أدق النتائج)","½ كوب سكر جوز الهند غير المكرر","3 ملاعق صغيرة بيكنج باودر","1 ملعقة صغيرة قرفة","½ ملعقة صغيرة جوزة الطيب","¼ ملعقة صغيرة ملح البحر","1.5 كوب تفاح مقطع مكعبات (قطّعه إلى مكعبات صغيرة جدًا)","½ كوب صلصة التفاح غير المحلاة","1 كوب حليب الصويا","2 ملعقة كبيرة سكر جوز الهند غير المكرر","1 ملعقة صغيرة قرفة"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (176° مئوية) وبطّن قالب رغيف بورق الزبدة.","ضع جميع المكونات الجافة في وعاء خلط كبير واخفقها. ثم أضف صلصة التفاح وحليب الصويا وحرّك حتى لا تبقى أي بقع جافة، دون الإفراط في الخلط. ثم أضف مكعبات التفاح بالتقليب الرفيق، مع الاحتفاظ بحفنة صغيرة لرشّها على الوجه.","اختياري: إذا كنت ستستخدم دوامة القرفة، فاخلط السكر والقرفة في وعاء صغير. ثم صبّ نصف عجين خبز التفاح في قالب الرغيف وانثر خليط القرفة الحلو فوقه في طبقة متساوية. (يمكنك الاحتفاظ بكمية صغيرة من الخليط لرشّها على النصف الثاني من العجين إن أردت.) ثم صبّ النصف المتبقي من العجين فوق الدوامة، مع بذل أقصى جهدك لفرده بالتساوي، دون خلط الدوامة بالعجين. وإذا احتفظت ببعض قطع التفاح، فانثرها على الوجه، واضغط عليها برفق وانثر أي خليط سكر/قرفة متبقٍّ فوق التفاح.","إذا تخطيت دوامة القرفة، فصبّ العجين كاملًا في قالب الرغيف المجهز وانثر قطع التفاح المحتفظ بها على الوجه.","اخبزه لمدة 45-55 دقيقة، أو حتى تخرج عود الأسنان المغروس في منتصف الرغيف نظيفًا تقريبًا، أو مع بضع فتات. ثم أخرجه من الفرن واتركه يبرد 10 دقائق على رف التبريد قبل نقل الرغيف إلى لوح التقطيع. واصل التبريد 5-10 دقائق أخرى إن استطعت الانتظار (فهذا يسهّل التقطيع). ثم قطّع الرغيف وبالهناء والشفاء."],
["زِن الدقيق للحصول على أفضل النتائج. إذا لم يكن لديك ميزان مطبخ، فاغرف الدقيق بالملعقة إلى كوب القياس وسوِّه بسكين مسطحة. لا تغرف الدقيق من الكيس أبدًا.","مثل معظم المخبوزات، لا تفرط في خلط العجين. عند إضافة المكونات السائلة إلى الجافة، حرّك حتى لا تبقى أي بقع دقيق وأضف قطع التفاح بالتقليب الرفيق.","قطّع التفاح إلى مكعبات صغيرة جدًا. فالقطع الصغيرة تتوزع بشكل أكثر تساويًا.","حضّر التفاح وقطّعه بعد تحضير بقية المكونات حتى لا يسمرّ. أو رشّ عليه عصير الليمون إذا كنت تعمل مسبقًا.","هذا الخبز رطب جدًا وتختلف الأفران عن بعضها. اخبز خبز التفاح النباتي حتى يخرج عود الأسنان المغروس في المنتصف جافًا تقريبًا. قد يستغرق ذلك وقتًا أقل قليلًا أو أكثر قليلًا بحسب فرنك. ابدأ بتفقد النضج عند مرور 45 دقيقة تقريبًا.","يُحفظ المتبقي مغطى في درجة حرارة الغرفة لمدة يومين، أو في الثلاجة لمدة تصل إلى 5 أيام، أو في الفريزر لمدة تصل إلى 3 أشهر. تأكد من أن الرغيف بارد تمامًا قبل التجميد."],
{"Optional Sweet Cinnamon Swirl":"دوامة القرفة الحلوة (اختياري)"})
R(9596706,"كوكيز الزنجبيل النباتي السهل [بدون زيت]",
"كوكيز الزنجبيل النباتي مقرمش من الخارج وطري وممضوغ من الداخل. مليء بتوابل الأعياد، يُحضّر في وعاء واحد وجاهز في 20 دقيقة فقط!",
"10 قطع كوكيز","قطعة كوكيز واحدة",
["200 غرام دقيق الشوفان حوالي 2 كوب إلا قليلًا","2 ملعقة صغيرة زنجبيل مطحون","1 ملعقة صغيرة قرفة","¼ ملعقة صغيرة قرنفل مطحون","1 ملعقة صغيرة بيكربونات الصودا","⅓ كوب دبس فاخر (مولاس)","⅓ كوب صلصة التفاح غير المحلاة","1-2 ملعقة كبيرة حليب نباتي عند الحاجة فقط","2-3 ملاعق كبيرة سكر أبيض لتغليف الكوكيز"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) وبطّن صينية خبز بورق الزبدة.","ضع جميع المكونات الجافة في وعاء كبير واخفقها جيدًا. ثم أضف الدبس وصلصة التفاح واخلط حتى لا تبقى أي بقع دقيق. أضف 1-2 ملعقة كبيرة من الحليب النباتي عند الحاجة فقط. (إذا كنت تزن الدقيق، فلن تحتاج إليه.)","قسّم العجين إلى 10 أجزاء، وشكّل كل جزء على هيئة كرة قطرها حوالي 1-1.5 بوصة. ثم لفّها في السكر (إن استخدمته)، وسطّحها قليلًا وضعها على صينية الخبز.","اخبزها لمدة 10 دقائق، ثم أخرجها من الفرن واتركها تبرد لمدة 5 دقائق على الأقل حتى تتماسك. بالهناء والشفاء!"],
["زِن الدقيق للحصول على أدق النتائج. إذا لم يكن لديك ميزان مطبخ، فاستخدم كوبين إلا قليلًا من دقيق الشوفان. إذا كنت تستخدم الميزان ولا تجري أي استبدالات، فلا يفترض أن تحتاج إلى أي حليب نباتي. وإذا غرفت الدقيق من الكيس (لا يُنصح بذلك)، فقد تحصل على دقيق أكثر من اللازم. لذا إذا بدا عجين الكوكيز جافًا جدًا بعد الخلط (يجب أن يكون لزجًا ورطبًا، راجع الصور أعلاه) فأضف 1-2 ملعقة كبيرة من الحليب عند الحاجة. اخبزه لمدة 10 دقائق، ولا تزد على ذلك. قد يبدو كوكيز الزنجبيل النباتي هذا غير ناضج عند 10 دقائق لكنه سيتماسك بسرعة إلى حد ما بعد إخراجه من الفرن. استخدم مغرفة كوكيز للحصول على قطع كوكيز زنجبيل متساوية الحجم. أو قسّم العجين إلى 10 أجزاء متساوية قبل تشكيل الكوكيز. للحصول على كوكيز أكثر قرمشة قليلًا، اضغط عليه قبل الخبز. وللحصول على كوكيز زنجبيل أكثر هشاشة وأكثر مضغًا، شكّله على هيئة كرات فقط واخبزه. لن ينتشر كثيرًا لكنه سينضج تمامًا في 10 دقائق من الخبز. استخدم يدين رطبتين لتشكيل الكوكيز لمنع العجين من الالتصاق بيديك. يُحفظ المتبقي مغطى أو في وعاء مغلق في درجة حرارة الغرفة لمدة 2-3 أيام. ومع ذلك، إذا كنت تعيش في مناخ حار/رطب، فقد يذوب السكر المغلِّف في درجة حرارة الغرفة. أو يمكنك تجميده في وعاء محكم الإغلاق لمدة تصل إلى شهرين."],
{"Optional Topping":"إضافة اختيارية"})
R(9602754,"مافن الشمندر الصحي",
"مافن الشمندر الصحي هذا وجبة خفيفة نابضة بالحياة ومغذية، مثالية للإفطار أو كحلوى!",
"12 كعكة مافن","حصة واحدة",
["2 × 398 مل (2 × 14 أونصة) شمندر معلب مصفى (حوالي 2.5 كوب شمندر مقطع مكعبات)","¼ كوب صلصة التفاح غير المحلاة","3 ملاعق كبيرة شراب القيقب","1 ملعقة صغيرة خل التفاح","300 غرام دقيق اللوز المقشر فائق النعومة حوالي 3 أكواب إلا قليلًا","2 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصودا","⅓ كوب رقائق شوكولاتة نباتية بالإضافة إلى القليل منها لتزيين المافن إن أحببت"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (176° مئوية) وبطّن قالب المافن بكؤوس من ورق الزبدة.","ضع جميع المكونات السائلة في الخلاط واخلطها حتى تصبح ناعمة تمامًا. ضعها جانبًا.","ثم اخفق المكونات الجافة معًا في وعاء كبير. اسكب المكونات السائلة المهروسة في الوعاء نفسه مع الدقيق وحرّك حتى تمتزج.","أضف رقائق الشوكولاتة إن استخدمتها بالتقليب الرفيق، ثم وزّع العجين على قوالب المافن الاثني عشر، بحيث تملأها إلى ما قبل الحافة تقريبًا.","اخبز المافن لمدة 28-30 دقيقة، أو حتى يخرج عود الأسنان المغروس في وسط قطعة المافن نظيفًا وجافًا.","أخرج القالب من الفرن واترك المافن يرتاح في درجة حرارة الغرفة لمدة 20-30 دقيقة على الأقل قبل نقله إلى رف سلكي ليتماسك تمامًا."],
["زِن الدقيق للحصول على أدق النتائج. إذا لم يكن لديك ميزان مطبخ، فاغرف الدقيق بالملعقة إلى كوب القياس واستخدم سكينًا لإزالة الزائد، بنتائج مماثلة. لا تغرف من الكيس!","إذا كنت تستخدم شمندرًا معلبًا، فتأكد من أنه ليس مخللًا! استخدم شمندرًا معلبًا في الماء فقط، بدون خل أو زيت لأن ذلك سيغير النكهة.","استخدم بيكنج باودر طازجًا وفعالًا. فالبيكنج باودر المفتوح في خزانتك منذ 6 أشهر أو أكثر قد يفقد فعاليته.","اضرب قالب المافن برفق على سطح صلب لسد أي فراغات في العجين قبل الخبز.","اترك المافن يبرد في القالب لمدة 20-30 دقيقة على الأقل قبل لمسه. فهو هش ويحتاج إلى وقت ليتماسك تمامًا قبل نقله إلى رف سلكي.","يُحفظ المتبقي في درجة حرارة الغرفة لمدة تصل إلى يومين، أو في الثلاجة لمدة تصل إلى 5 أيام، أو في الفريزر لمدة تصل إلى 3 أشهر."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","Optional":"اختياري"})
R(9602755,"بودينج الشيا بالفراولة",
"بودينج الشيا بالفراولة حلوى كريمية ومغذية تُحضّر بمزج الفراولة الطازجة وبذور الشيا والحليب النباتي.",
"حصتان","حصة واحدة",
["1 كوب فراولة طازجة","1 كوب حليب كاجو غير محلّى (أو أي حليب غير لبني من اختيارك)","4 ملاعق كبيرة بذور الشيا","1 ملعقة كبيرة شراب القيقب (اختياري لمزيد من الحلاوة)"],
["اخلط الفراولة والحليب في خلاط صغير لتحضير حليب الفراولة.","عندما يصبح ناعمًا، انقل حليب الفراولة إلى برطمان أو وعاء زجاجي وأضف بذور الشيا. قلّب جيدًا وضعه في الثلاجة لمدة 6 ساعات، أو طوال الليل.","تمتّع به مع إضافة فراولة طازجة أخرى أو فاكهة أخرى أو مكسرات أو جرانولا أو شوفان و/أو جوز هند مبشور."],[])
R(9602951,"بديل البيض بالشيا (أو بذور الكتان أيضًا!)",
"بديل البيض بالشيا (أو بالكتان) بسيط ومتعدد الاستخدامات. تعلّم كيفية استخدام هذا البديل في جميع وصفات المخبوزات المفضلة لديك!",
"1","بيضة واحدة",
["1 ملعقة كبيرة بذور الشيا أو بذور الكتان المطحونة","3 ملاعق كبيرة ماء"],
["في وعاء صغير، اخلط الشيا أو الكتان مع الماء. اتركه 5 دقائق (أو أكثر) ثم استخدمه في وصفاتك المفضلة."],
["لا تحتاج إلى طحن البذور لتحضير بديل البيض بالشيا هذا. ومع ذلك، إذا أردت إخفاء قوام البذور عن أي شخص صعب الإرضاء، فافعل ذلك. أو، إذا كنت لا تريد رؤيتها في المنتج النهائي، فاستخدم البذور البيضاء بدلًا من السوداء. ورغم أنه يمكنك استخدام بديل البيض بالكتان وبديل البيض بالشيا بالتبادل في معظم وصفات المخبوزات، فإنني أفضّل الشيا بسبب طعمها المحايد. ومع ذلك، أستخدم ما يتوفر لدي في المخزن، لذا استخدم ما لديك فحسب!"])
R(9604269,"صلصة جبن الجوز النباتية [بدون زيت]",
"صلصة جبن الجوز النباتية مليئة بالنكهة، وتحتاج إلى 5 مكونات فقط وتُحضّر في خمس دقائق فقط! دون طهي أو تقطيع.",
"6 حصص","حصة واحدة",
["1¼ كوب جوز","2 ملعقة كبيرة خميرة غذائية","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة ملح البحر","¾ كوب ماء ساخن بالإضافة إلى ملعقة كبيرة أو ملعقتين إضافيتين اختياريتين للوصول إلى القوام المطلوب"],
["باستخدام غلاية أو قدر صغير، اغلِ كوبًا أو كوبين من الماء الطازج. (لأن جزءًا منه سيتبخر.)","ضع جميع المكونات باستخدام ¾ كوب فقط من الماء الساخن في الخلاط واخلطها حتى تصبح ناعمة وكريمية. سيستغرق الأمر حوالي دقيقة تقريبًا ليتفتت الجوز تمامًا ويصبح ناعمًا. وإذا لزم الأمر، أوقف الخلاط وأعد تشغيله حتى تصل إلى القوام المطلوب. تذوّق التتبيل وعدّله إذا لزم الأمر. وإذا كنت تفضل صلصة أخف، فأضف 1-2 ملعقة كبيرة إضافية من الماء وأعد الخلط."],
["لا حاجة إلى نقع الجوز إذا كان لديك خلاط قوي. وإلا فانقعه لمدة 30 دقيقة في ماء ساخن ثم صفّه قبل إضافته إلى الخلاط. إذا كنت لا تستخدم خلاطًا قويًا، فأوقفه وانتظر 30 ثانية ثم أعد تشغيله حتى يصبح جبن الجوز ناعمًا. (سيساعد ذلك على منع ارتفاع حرارة الخلاط الأقل قوة.) أضف 1-2 ملعقة كبيرة إضافية من الماء الساخن عند الحاجة للوصول إلى القوام المطلوب، إذا كنت تفضل صلصة أخف. غيّر فيها! إذا أردت تغيير النكهات، فاستبدل مسحوق البصل بمسحوق الثوم أو البابريكا أو البابريكا المدخنة أو أي توابل أخرى تريدها. (ضع في اعتبارك أن التوابل الداكنة ستغير لون صلصة جبن الجوز.) يُحفظ المتبقي في وعاء مغلق في الثلاجة لمدة 3 أيام. أعد تسخينه قبل التقديم."])
R(9605778,"عجينة فطيرة من القمح الكامل بدون زيت",
"عجينة فطيرة بسيطة بدون زيت، نباتية وخالية من المكسرات، مصنوعة من مزيج من الدقيق الأبيض ودقيق القمح الكامل لخيار حلوى أكثر صحة! سهلة التحضير ومثالية للفطائر الحلوة والمالحة على حد سواء!",
"8 شرائح","حصة واحدة",
["90 غرامًا (حوالي ¾ كوب) دقيق متعدد الاستخدامات غير مبيّض أو 90 غرامًا من دقيق اللوز","80 غرامًا (حوالي ¾ كوب) دقيق القمح الكامل الأبيض المعروف أيضًا بالقمح الكامل الناعم أو دقيق المعجنات من القمح الكامل","1 حبة أفوكادو متوسطة ناضجة مقشرة ومنزوعة النواة","¼ ملعقة صغيرة ملح البحر (زدها إلى ½-¾ ملعقة صغيرة للفطائر المالحة)","4 ملاعق كبيرة حليب جوز الهند غير المحلّى من Thai Kitchen رجّ العلبة جيدًا جدًا قبل فتحها! (إذا استخدمت خيار دقيق اللوز، فيمكنك استخدام أي حليب غير لبني.)","1-2 ملعقة كبيرة ماء عند الحاجة فقط!","2 ملعقة كبيرة سكر جوز الهند أو أي سكر حبيبات من اختيارك (يُحذف للفطائر المالحة)","1 ملعقة صغيرة قرفة (تُحذف للفطائر المالحة)"],
["ادهن طبق فطيرة قطره 9 بوصات بقليل من الدهن أو قصّ قطعة دائرية من ورق الزبدة لتوضع داخله. ضعه جانبًا.","ضع جميع المكونات ما عدا الماء في محضّر الطعام واخلطها حتى تمتزج، دون الإفراط في الخلط.","رشّ قليلًا من الدقيق على ورقة زبدة على سطح المطبخ، واجمع الخليط من المحضّر بيديك لتشكيل كرة. إذا كان الخليط جافًا جدًا أو متفتتًا فأضف ملعقة كبيرة من الماء إلى العجين واخلطها جيدًا جدًا بيديك. (لن تحتاج إلى الماء إذا وزنت الدقيق بميزان المطبخ.) تريد كرة من العجين بقوام يشبه عجينة اللعب. ليست جافة جدًا، وليست مبللة إلى درجة أن تصبح لزجة.","ضع العجين على ورقة الزبدة المرشوشة بالدقيق وانثر قليلًا من الدقيق فوق كرة العجين وعلى النشابة (الشوبك). ثم استخدم النشابة لفرد العجين على هيئة دائرة عرضها حوالي 10-11 بوصة. (أعرض قليلًا من طبقك.) يجب أن يكون سمك العجين حوالي 1/4 بوصة، فحاول فرده بأكبر قدر ممكن من التساوي.","الآن، استخدم ورقة الزبدة لقلب العجين فوق طبق الفطيرة. ثم انزع ورقة الزبدة برفق. استخدم يديك لضغط القاعدة في الطبق، على طول القاع والحواف. وإذا ظهرت أي تمزقات، فاستخدم أصابع مبللة لضغط العجين وإعادة إغلاقه.","ثم دُر حول الحواف واستخدم سكينًا لقص أي عجين زائد.","اختياري: استخدم أصابعك لعمل تصميم زخرفي حول الحواف، إن أردت. (انظر صور الخطوات أعلاه.) لا يلزم أن يكون مثاليًا!","اغرز قاع القاعدة بشوكة في كل مكان للسماح للبخار بالخروج، ثم اخبزها.","إذا كنت تحضّر فطيرة بحشوة لا تحتاج إلى خبز: سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) واخبز القاعدة وحدها (خبز أعمى) لمدة 15-20 دقيقة، حتى تصبح الحواف ذهبية اللون ثم أخرجها من الفرن. اتركها تبرد تمامًا قبل الحشو للحصول على فطيرة لا تحتاج إلى مزيد من الخبز. مثل فطيرة الليمون أو فطيرة الليمون الأخضر (كي لايم) أو فطيرة الفراولة الخاصة بي.","إذا كنت تحضّر فطيرة تحتاج إلى وقت طهي طويل: سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175° مئوية) (مثل فطيرة التوت الأزرق أو التفاح) واخبز القاعدة وحدها (خبز أعمى) لمدة 10-15 دقيقة. ثم أخرجها من الفرن واحشها (لا حاجة إلى تركها تبرد أولًا) وواصل الخبز للمدة الموصى بها لتلك الوصفة. (عادةً ما بين 40-60 دقيقة.) أو لفطيرة تحتاج إلى وقت طهي طويل ولا تتطلب خبز القاعدة وحدها، احشها وهي نيئة واخبزها وفق تعليمات فطيرتك. على سبيل المثال، فطيرة البيكان الخاصة بي لا تتطلب خبز القاعدة وحدها."],
["***شاهد العجينة أثناء التحضير في الفيديو أعلاه لفطيرة الليمون النباتية الخاصة بنا*** للحصول على أفضل النتائج، استخدم ميزان مطبخ وزِن الدقيق. فالاعتماد على الكيل بالأكواب أقل دقة من الوزن. حاول ألا تفرط في خلط المزيج في محضّر الطعام. شغّله على نبضات متقطعة حتى يمتزج ثم انقله إلى سطح نظيف لتواصل باليد. تأكد من رشّ قليل من الدقيق على سطح العمل والنشابة لمنع الالتصاق. أثناء فرد العجين، من المفيد رفعه وتحريكه بين مرات الفرد حتى لا يلتصق كثيرًا. لا تضف الماء إلا عند الحاجة. إذا استخدمت ميزان المطبخ، فلا يفترض أن تحتاج إلى أي ماء. إذا كنت تعمل مسبقًا، فيمكنك تشكيل العجين على هيئة كرة ولفّه جيدًا ووضعه في الثلاجة. ثم أخرجه من الثلاجة قبل فرده بحوالي 20 دقيقة. إذا كنت تحضّر فطيرة بوقت خبز طويل (مثل التفاح أو التوت الأزرق) فغطِّ حواف الفطيرة بحلقة من ورق الألمنيوم (قصّ حلقة من ورق الألمنيوم) أو واقي حواف الفطائر (pie shield) إن كان لديك، لمنع احتراق الحواف."],
{"Optional":"اختياري","Preparation Directions":"طريقة التحضير","Baking Directions":"طريقة الخبز"})
R(9605903,"صلصة ألفريدو النباتية السهلة",
"صلصة ألفريدو النباتية الشهية تستخدم مكونات بسيطة وتُحضّر في 5 دقائق!",
"6 حصص","حصة واحدة",
["1 كوب كاجو نيء","2 ملعقة كبيرة عصير ليمون حوالي نصف ليمونة كبيرة","¾ كوب ماء ساخن","¼ ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة مسحوق البصل","⅛ ملعقة صغيرة زعتر مجفف","½ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل أسود","جبن بارميزان نباتي"],
["ضع جميع المكونات في خلاط قوي واخلطها على سرعة عالية حتى تصبح ناعمة وكريمية. واصل الخلط للتأكد من عدم وجود أي قطع كاجو سائبة. أضف 2-3 ملاعق كبيرة من جبن البارميزان النباتي إن رغبت.","قدّمها مع النودلز أو الخضار المفضلة لديك."],
["استخدم ماءً ساخنًا حتى لا تحتاج إلى تسخين الصلصة في مقلاة لاحقًا.","إذا لم يكن لديك خلاط قوي، فانقع الكاجو في ماء مغلي ساخن لمدة 20-30 دقيقة لتليينه. ثم صفّه واخلطه مع بقية المكونات.","إذا كنت لا تستطيع تناول الكاجو أو المكسرات، فاستخدم بذور عباد الشمس بنتائج مماثلة.","تُحفظ الصلصة المتبقية في الثلاجة لمدة 4-5 أيام، أو تُجمّد في أوعية مناسبة للفريزر لمدة تصل إلى 3 أشهر."],
{"Optional Garnish":"تزيين اختياري"})
R(9608562,"شوربة البروكلي والشيدر النباتية",
"شوربة بروكلي وشيدر نباتية صحية ومشبعة ولذيذة للغاية!",
"6 حصص","حصة واحدة",
["1 بصلة صفراء مفرومة ناعمًا","1 عود كرفس كبير مقطع مكعبات","2 جزرة كبيرة مقطعة مكعبات","4 أكواب زهرات قرنبيط حوالي رأس صغير واحد","1 رطل بطاطس صفراء مقشرة ومقطعة إلى مكعبات بحجم 1 بوصة (حوالي 3.5 أكواب مكعبات)","2 كوب بطاطا حلوة مقطعة مكعبات حوالي حبة متوسطة واحدة","4 أكواب مرق خضار قليل الصوديوم","2 ملعقة صغيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","4 أكواب بروكلي مقطع إلى زهرات بحجم اللقمة (طازج أو مجمد)","1 كوب كاجو نيء","¾ كوب ماء بالإضافة إلى 1-2 ملعقة كبيرة عند الحاجة","⅓ كوب خميرة غذائية","2 ملعقة كبيرة خل التفاح","2 ملعقة كبيرة نشا التابيوكا أو دقيق التابيوكا","1 ملعقة كبيرة معجون الميسو الأبيض","1 ملعقة صغيرة خردل أصفر","½ ملعقة صغيرة مسحوق البصل","¼ ملعقة صغيرة ملح البحر"],
["ضع البصل والكرفس والجزر في قدر كبير مع ملعقة كبيرة أو ملعقتين من الماء. قلّبها على حرارة متوسطة حتى تلين، حوالي 5 دقائق. أضف مزيدًا من الماء عند الحاجة لمنع الالتصاق.","ثم أضف القرنبيط ونوعي البطاطس والمرق وجميع التوابل إلى القدر. اتركها حتى تغلي على نار عالية، ثم خفّف إلى متوسطة منخفضة. اطهُها حتى تلين الخضار، حوالي 8-10 دقائق.","في هذه الأثناء، في قدر أو مقلاة منفصلة، غطِّ البروكلي بالماء واتركه حتى يغلي، ثم خفّف الحرارة ليغلي بهدوء واطهُه حتى يلين بالشوكة، حوالي 4-6 دقائق. صفّه وضعه جانبًا.","بينما تُطهى الشوربة والبروكلي، ضع جميع مكونات صلصة الشيدر في الخلاط. اخلطها حتى تصبح ناعمة وضعها جانبًا.","استخدم الخلاط اليدوي لهرس قدر الشوربة حتى تصبح ناعمة. ثم أضف البروكلي المطبوخ وصلصة الشيدر وحرّك جيدًا. بالهناء والشفاء."],
["إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو في ماء مغلي ساخن لمدة 15-20 دقيقة ثم صفّه. سيؤدي ذلك إلى تليينه، مما يسهّل خلطه.","تأكد من عدم وجود قطع كاجو سائبة في صلصة الجبن للحصول على أفضل قوام. اخلطها لفترة أطول قليلًا إذا لزم الأمر لتصبح ناعمة.","اطهُ البروكلي على حدة. يمكنك استخدام جهاز بخار أو قدر آخر أو مقلاة، لكن الأفضل أن يكون على حدة. بعد هرس الشوربة، أضف زهرات البروكلي المطبوخة إلى القدر.","قطّع البروكلي إلى زهرات صغيرة بحجم اللقمة لأنها ستبقى كاملة ولن تُهرس مع بقية المكونات.","استخدم قدرًا عميقًا لتجنب الرذاذ عند خلط الشوربة بالخلاط اليدوي.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام، أو يُجمّد في وعاء محكم الإغلاق لمدة 3-4 أشهر."],
{"For the Vegan Cheddar Sauce":"لصلصة الشيدر النباتية"})
R(9609089,"صلصة سالسا الطماطم الطازجة",
"سالسا طماطم منزلية طازجة ولذيذة، حارة ومليئة بالنكهة ومثالية كوجبة خفيفة.",
"4 حصص","حصة واحدة",
["3 أكواب طماطم مقطعة مكعبات (حوالي 4 حبات متوسطة أو 6 حبات صغيرة)","½ كوب بصل أحمر مقطع مكعبات (حوالي نصف بصلة)","2-3 حبات هالبينو (مفرومة ناعمًا)","1 حبة فلفل رومي أحمر (مقطعة مكعبات)","½ كوب كزبرة خضراء (مفرومة ناعمًا)","2 ملعقة كبيرة عصير ليمون أخضر (حوالي ليمونة خضراء واحدة)","½ ملعقة صغيرة ملح البحر (أو حسب الرغبة)","½ ملعقة صغيرة بابريكا مدخنة","¼ ملعقة صغيرة فلفل كايين (اختياري)"],
["قطّع جميع الخضار وضعها في وعاء خلط. ثم أضف عصير الليمون الأخضر والتوابل واخلط جيدًا.","اختياري: اخلط 1 كوب من سالسا الطماطم في الخلاط، ثم أعده إلى الوعاء وحرّك لدمجه للحصول على قوام أقل خشونة.","ضعها في الثلاجة لمدة ساعة (أو أكثر) لتبرد وتتمازج النكهات. ثم قدّمها."],[])
R(9610207,"خبز القمح الأسود (الحنطة السوداء)",
"وصفة بسيطة ولذيذة لخبز القمح الأسود (الحنطة السوداء) يسهل تحضيرها، بدون خميرة وبدون بيض وبدون زيت وبدون وقت للتخمر وبدون عجن.",
"12 شريحة","حصة واحدة",
["300 غرام دقيق القمح الأسود (الحنطة السوداء) حوالي 2¼ كوب","3 ملاعق صغيرة بيكنج باودر","1 ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق البصل اختياري","¼ كوب طحينة","¼ كوب صلصة التفاح غير المحلاة","1 كوب ماء مفلتر","1-2 ملعقة كبيرة بذور السمسم أو بذور الخشخاش و/أو بذور اليقطين"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (176° مئوية) وبطّن قالب رغيف بورق الزبدة.","ضع الدقيق والبيكنج باودر والملح ومسحوق البصل (إن استخدمته) في وعاء خلط كبير. حرّك لدمجها. ثم أضف الطحينة وصلصة التفاح والماء واخلط حتى تمتزج ويصبح لديك عجين سميك.","انقل الخليط إلى قالب الرغيف وافرده وسوِّ وجهه بملعقة سيليكون مسطحة.","اختياري: انثر البذور التي تختارها واضغط عليها برفق في الرغيف.","اخبزه لمدة 45-50 دقيقة تقريبًا، أو حتى يخرج عود الأسنان المغروس في منتصف الرغيف نظيفًا وجافًا.","أخرجه من الفرن واتركه يبرد إلى درجة حرارة الغرفة قبل التقطيع."],
["زِن الدقيق للحصول على أفضل النتائج. يختلف حجم الدقيق باختلاف طرق القياس، مثل الغرف والتسوية مقابل وضع الدقيق بالملعقة في كوب القياس. استخدم ميزان مطبخ للحصول على أدق قياس للدقيق.","استخدم بيكنج باودر طازجًا وفعالًا! فالبيكنج باودر المفتوح في خزانتك منذ 6 أشهر أو أكثر قد يبدأ في فقدان فعاليته.","استخدم ورق الزبدة لتبطين قالب الرغيف. فهذا لا يجنّبك الدهون الإضافية الناتجة عن دهن القالب فحسب، بل يسهّل أيضًا إخراج خبز القمح الأسود من القالب بعد الخبز.","سيختلف وقت الطهي بحسب حجم قالب الرغيف، لذا تحقق دائمًا من \"النضج\" بغرز عود أسنان في المنتصف لترى ما إذا كان يخرج نظيفًا. الرغيف عندي مثالي عند 45 دقيقة.","اتركه يبرد. امنح نفسك وقتًا إضافيًا ليبرد الرغيف. 60 دقيقة على الأقل على"],
{"Optional Toppings":"إضافات اختيارية"})
R(9610471,"موكا مثلجة صحية [نباتية + قليلة السكر]",
"شوكولاتة مثلجة صحية قليلة السكر ومحلّاة طبيعيًا ولذيذة للغاية. هذه القهوة المثلجة النباتية الخالية من الشعور بالذنب جاهزة في 5 دقائق!",
"حصة واحدة","حصة واحدة",
["1 حبة موز كبيرة مجمدة","⅔ كوب حليب صويا غير محلّى أو أي حليب من اختيارك","1 ملعقة كبيرة مسحوق كاكاو نيء غير محلّى","1.5 ملعقة صغيرة قهوة سريعة التحضير يمكنك استخدام قهوة منزوعة الكافيين إذا لزم الأمر","2-3 حبات تمر منزوعة النوى","⅓ كوب مكعبات ثلج","حليب مرغّى","مزيد من مسحوق الكاكاو","قرفة"],
["ضع جميع المكونات في الخلاط واخلطها حتى تصبح ناعمة وكريمية.","اسكبها في كوب وزيّنها إن أحببت. بالهناء والشفاء."],
["استخدم موزًا ناضجًا جدًا تم تجميده للحصول على أفضل النتائج. فإذا كنت تجمّد الموز البني لتصنع منه خبز الموز يومًا ما، فهذا بالضبط نوع الموز الذي تريده لهذه القهوة المثلجة النباتية. إذا كنت تحب الحلاوة، فأضف حبتي تمر إضافيتين. يمكنك البدء بـ 2-3 حبات، ثم تذوّق وأضف المزيد عند الحاجة، وأعد الخلط. ليس لديك خلاط قوي؟ انقع التمر مسبقًا في ماء بارد لمدة 15-20 دقيقة تقريبًا ثم صفّه واخلطه. سيساعد ذلك على تليينه ومنع القطع المتفتتة في الموكا المثلجة النباتية. إذا لم يتوفر لديك موز مجمد، فيمكنك استخدام موز طازج، لكن أضف ⅓ كوب إضافيًا من مكعبات الثلج."],
{"Optional Toppings":"إضافات اختيارية"})
